import {registerCadenceImport} from './cadence-import.js';
import {orientation,changeOrientation,nodeMatrix,transformPoint,nodeBounds} from './geometry.js';
import {VERSION,clone,validate,parseImport,endpoints,getPin,assignNet,renameNet,mergeNets,connect,warnings,diff,bundle,aiDocument,demo} from './core.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
const key=(kind,id)=>JSON.stringify([kind,id]);
const storageKey='circuit-atlas-project-v1';
let current=demo(), state={current,baseline:clone(current),layout:{},review:null},cellId=current.top,selected=null,listMode='instances',view='graph',wireMode=false,pending=null,undo=[],redo=[],camera={x:0,y:0,z:1},drag=null,saveTimer,toastTimer,hasSaved=false;
try{hasSaved=!!localStorage.getItem(storageKey);}catch{}
const cell=()=>state.current.cells.find(c=>c.id===cellId)||state.current.cells[0];
const positions=()=>{if(!Object.hasOwn(state.layout,cell().id))Object.defineProperty(state.layout,cell().id,{value:{},writable:true,enumerable:true,configurable:true});return state.layout[cell().id];};
function notify(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',3500);$('#status').textContent=message;}
function persist(){clearTimeout(saveTimer);saveTimer=setTimeout(()=>{try{localStorage.setItem(storageKey,JSON.stringify(bundle(state)));$('#status').textContent='이 브라우저에 자동 저장됨'+' · 파일 내보내기로 별도 보관';}catch{$('#status').textContent='브라우저 저장 실패 · 프로젝트 파일로 내보내세요';}},350);}
function checkpoint(){undo.push(clone(state));if(undo.length>60)undo.shift();redo=[];}
function edit(label,fn,{structural=true}={}){const before=clone(state);try{fn();validate(state.current);undo.push(before);if(undo.length>60)undo.shift();redo=[];if(structural)state.review=null;render();persist();notify(label);return true;}catch(e){state=before;notify(e.message);return false;}}
function restore(direction){const from=direction==='undo'?undo:redo,to=direction==='undo'?redo:undo;if(!from.length)return;to.push(clone(state));state=from.pop();if(!state.current.cells.some(c=>c.id===cellId))cellId=state.current.top;pending=null;selected=null;render();persist();}
function modal(title,html){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=html;$('#modal').showModal();}
const close=()=>$('#modal').close();
$('#closeModal').onclick=close;
function confirmAction(title,description,fn,label='적용'){modal(title,`<p>${esc(description)}</p><div class="modal-actions"><button id="cancelAction">취소</button><button class="primary" id="confirmAction">${esc(label)}</button></div>`);$('#cancelAction').onclick=close;$('#confirmAction').onclick=()=>{close();fn();};}
function saveFile(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);notify(`${name} 다운로드`);}
const basename=()=>cell().name.replace(/[^\p{L}\p{N}_-]/gu,'_')||'circuit';
function nodeHeight(i){return 76+Math.ceil(i.pins.length/2)*27;}
function allNodes(){return [...cell().instances.map(i=>({kind:'instance',id:i.id,w:184,h:nodeHeight(i),data:i})),...cell().ports.map(p=>({kind:'port',id:p.name,w:140,h:76,data:p})),...cell().nets.map(n=>({kind:'net',id:n.name,w:Math.min(340,Math.max(108,n.name.length*8+28)),h:38,data:n}))];}
function autoLayout(){const p=positions(),c=cell();const rowH=Math.max(215,...c.instances.map(nodeHeight).map(x=>x+90));c.instances.forEach((i,n)=>{p[key('instance',i.id)]={...p[key('instance',i.id)],x:120+(n%2)*400,y:100+Math.floor(n/2)*rowH};});c.nets.forEach((n,j)=>{p[key('net',n.name)]={x:830,y:80+j*92};});c.ports.forEach((n,j)=>{p[key('port',n.name)]={...p[key('port',n.name)],x:1100,y:70+j*125};});}
function ensurePositions(){const p=positions();if(!Object.keys(p).length)autoLayout();let n=0;for(const node of allNodes()){const k=key(node.kind,node.id);if(!p[k]||!Number.isFinite(p[k].x)||!Number.isFinite(p[k].y)||Math.abs(p[k].x)>1e7||Math.abs(p[k].y)>1e7)p[k]={x:150+(n%3)*300,y:100+Math.floor(n/3)*230};n++;}}
function pinPosition(ref){
 const p=positions()[key(ref.kind,ref.id)];
 const i=ref.kind==='instance'?cell().instances.find(x=>x.id===ref.id):null;
 const n=i?i.pins.findIndex(x=>x.name===ref.pin):1;
 const w=i?184:140,h=i?nodeHeight(i):76;
 const m=nodeMatrix(p,w,h),localX=i?(n%2?w:0):w,localY=i?79+Math.floor(n/2)*27:48;
 const point=transformPoint(m,localX,localY),sign=n%2?1:-1;
 return {...point,dx:m[0]*sign,dy:m[1]*sign,lead:30+Math.floor(n/2)*12};
}
function displayTransform(p,w,h){return `matrix(${nodeMatrix(p,w,h).join(' ')})`;}
function graphBounds(){const p=positions();return allNodes().map(n=>nodeBounds(p[key(n.kind,n.id)],n.w,n.h));}
function transformSelected(action){
 const kind=selected?.kind==='pin'?'instance':selected?.kind;
 if(!['instance','port'].includes(kind)){notify('먼저 회전·반전할 소자 또는 포트를 선택하세요.');return;}
 const id=selected.id;
 edit(action==='rotate'?'선택 항목을 시계 방향으로 90° 회전':'선택 항목을 화면 기준 좌우 반전',()=>{
   const p=positions(),k=key(kind,id);p[k]=changeOrientation(p[k],action);
 },{structural:false});
}
function panCamera(dx,dy){camera.x-=dx;camera.y-=dy;applyCamera();}
function refAttrs(ref){return `data-kind="${ref.kind}" data-id="${esc(ref.id)}" data-pin="${esc(ref.pin??ref.id)}"`;}
function activeNet(){if(selected?.kind==='net')return selected.id;if(selected?.kind==='pin'){try{return getPin(cell(),selected).net;}catch{}}return null;}
function renderGraph(){ensurePositions();const c=cell(),p=positions(),active=activeNet();let wires='',nodes='',nets='';for(const net of c.nets){const pos=p[key('net',net.name)],nx=pos.x,ny=pos.y+19;for(const e of endpoints(c,net.name)){const start=pinPosition(e),exitX=start.x+start.dx*start.lead,exitY=start.y+start.dy*start.lead,route=start.dy===0?`H ${exitX} V ${ny} H ${nx}`:`V ${exitY} H ${nx-24} V ${ny} H ${nx}`;wires+=`<path class="wire ${active===net.name?'selected':active!==null?'faded':''}" data-net="${esc(net.name)}" d="M ${start.x} ${start.y} ${route}"/>`;}}
 for(const i of c.instances){const pos=p[key('instance',i.id)],sel=selected?.id===i.id&&['instance','pin'].includes(selected.kind);nodes+=`<g class="device ${sel?'selected':''}" data-kind="instance" data-id="${esc(i.id)}" transform="${displayTransform(pos,184,nodeHeight(i))}"><rect class="body" width="184" height="${nodeHeight(i)}" rx="8"/><text class="device-name" x="14" y="24">${esc(short(i.name,12))}<title>${esc(i.name)}</title></text><text class="device-type" x="168" y="24" text-anchor="end">${esc(i.kind==='symbol'?'심볼':(i.kind||'CELL').toUpperCase().slice(0,3))}</text><text class="cell-name" x="14" y="45">${esc(short(i.cell,22))}<title>${esc(i.cell)}</title></text><line x1="12" y1="57" x2="172" y2="57" stroke="#3a505c"/>`;
 i.pins.forEach((pin,j)=>{const ref={kind:'instance',id:i.id,pin:pin.name},x=j%2?184:0,y=79+Math.floor(j/2)*27;nodes+=`<g class="pin ${pin.net===null?'unconnected':''} ${pending&&JSON.stringify(pending)===JSON.stringify(ref)?'pending':''}" ${refAttrs(ref)}><circle cx="${x}" cy="${y}" r="6"/><text x="${j%2?170:14}" y="${y+4}" text-anchor="${j%2?'end':'start'}">${esc(short(pin.name,10))}</text><title>${esc(i.name)} / ${esc(pin.name)} → ${esc(pin.net??'미연결')}</title></g>`;});nodes+='</g>';}
 for(const port of c.ports){const pos=p[key('port',port.name)];nodes+=`<g class="device top-port ${selected?.kind==='port'&&selected.id===port.name?'selected':''}" data-kind="port" data-id="${esc(port.name)}" transform="${displayTransform(pos,140,76)}"><rect class="body" width="140" height="76" rx="8"/><text class="cell-name" x="12" y="22">PORT · ${esc(port.direction||'unknown')}</text><text class="device-name" x="12" y="51">${esc(short(port.name,13))}</text><g class="pin ${port.net===null?'unconnected':''}" ${refAttrs({kind:'port',id:port.name,pin:port.name})}><circle cx="140" cy="48" r="6"/><title>${esc(port.name)} → ${esc(port.net??'미연결')}</title></g></g>`;}
 for(const net of c.nets){const pos=p[key('net',net.name)],w=Math.min(340,Math.max(108,net.name.length*8+28));nets+=`<g class="net-node ${active===net.name?'selected':''}" data-kind="net" data-id="${esc(net.name)}" transform="translate(${pos.x},${pos.y})"><rect width="${w}" height="38" rx="5"/><circle cx="0" cy="19" r="4"/><text x="13" y="24">${esc(short(net.name,37))}</text><title>${esc(net.name)} · ${endpoints(c,net.name).length}개 연결점${net.global?' · global':''}</title></g>`;}
 $('#wires').innerHTML=wires;$('#nodes').innerHTML=nodes;$('#netnodes').innerHTML=nets;
 for(const group of $$('#nodes > .device')){
   if(!orientation(p[key(group.dataset.kind,group.dataset.id)]).mirrored)continue;
   for(const text of group.querySelectorAll('text')){
     text.setAttribute('transform',`translate(${2*Number(text.getAttribute('x'))} 0) scale(-1 1)`);
     const anchor=text.getAttribute('text-anchor')||'start';
     text.setAttribute('text-anchor',anchor==='start'?'end':anchor==='end'?'start':anchor);
   }
 }
 applyCamera();
}
const short=(x,n)=>String(x).length>n?String(x).slice(0,n-1)+'…':x;
function applyCamera(){$('#viewport').setAttribute('transform',`translate(${camera.x},${camera.y}) scale(${camera.z})`);$('#zoomLabel').textContent=Math.round(camera.z*100)+'%';}
function fit(){ensurePositions();const nodes=allNodes();if(!nodes.length){camera={x:0,y:0,z:1};applyCamera();return;}const bounds=graphBounds(),minX=Math.min(...bounds.map(b=>b.minX))-50,minY=Math.min(...bounds.map(b=>b.minY))-65,maxX=Math.max(...bounds.map(b=>b.maxX))+50,maxY=Math.max(...bounds.map(b=>b.maxY))+65;const r=$('#canvas').getBoundingClientRect();if(!r.width||!r.height)return;const z=Math.max(.04,Math.min(1.4,r.width/(maxX-minX),r.height/(maxY-minY)));camera={x:(r.width-(maxX-minX)*z)/2-minX*z,y:(r.height-(maxY-minY)*z)/2-minY*z,z};applyCamera();}
function zoom(mult,x,y){const r=$('#canvas').getBoundingClientRect();x??=r.width/2;y??=r.height/2;const z=Math.max(.04,Math.min(3,camera.z*mult));camera.x=x-(x-camera.x)*z/camera.z;camera.y=y-(y-camera.y)*z/camera.z;camera.z=z;applyCamera();}
function select(kind,id,pin){selected={kind,id,...(pin?{pin}:{})};render();}
function renderExplorer(){const c=cell(),query=$('#search').value.toLowerCase();const rows=listMode==='instances'?[...c.instances.map(i=>({kind:'instance',id:i.id,name:i.name,sub:i.cell,icon:i.kind==='nmos'?'N':i.kind==='pmos'?'P':'IC'})),...c.ports.map(p=>({kind:'port',id:p.name,name:p.name,sub:'Top-level port',icon:'↗'}))]:c.nets.map(n=>({kind:'net',id:n.name,name:n.name,sub:`${endpoints(c,n.name).length}개 연결점${n.global?' · global':''}`,icon:'⌁'}));$('#explorer').innerHTML=rows.filter(r=>(r.name+' '+r.sub).toLowerCase().includes(query)).map(r=>`<button data-kind="${r.kind}" data-id="${esc(r.id)}" class="${selected?.kind===r.kind&&selected?.id===r.id?'selected':''}"><span class="item-icon">${r.icon}</span><span class="item-text"><strong>${esc(r.name)}</strong><small>${esc(r.sub)}</small></span></button>`).join('')||'<p class="empty">일치하는 항목이 없습니다.</p>';}
function netOptions(value){return '<option value="">— 미연결 —</option>'+cell().nets.map(n=>`<option value="${esc(n.name)}" ${n.name===value?'selected':''}>${esc(n.name)}</option>`).join('');}
function renderInspector(){const c=cell();let html='';let s=selected;if(s?.kind==='pin')s={kind:'instance',id:s.id};if(s?.kind==='instance'){const i=c.instances.find(i=>i.id===s.id);if(!i){selected=null;return renderInspector();}html=`<span class="badge">INSTANCE / ${(esc(i.kind||'generic')).toUpperCase()}</span><h2>${esc(i.name)}</h2><p class="meta">${esc(i.library||'—')} / ${esc(i.cell)}<br>원본 방향: ${esc(i.orientation||'미제공')} · 화면은 연결 중심 재배치</p><label class="field">인스턴스 이름<input id="instanceName" value="${esc(i.name)}"></label><button id="saveName">이름 적용</button><div class="section-label">PIN CONNECTIONS · ${i.pins.length}</div>`+i.pins.map(p=>`<div class="pin-row"><code title="${esc(p.name)}">${esc(p.name)}</code><select aria-label="${esc(p.name)} 연결 넷" data-edit-pin="${esc(p.name)}">${netOptions(p.net)}</select><button title="연결 해제" aria-label="${esc(p.name)} 연결 해제" data-disconnect="${esc(p.name)}">×</button></div>`).join('')+`<div class="sub-actions"><button id="newNetBtn">＋ 넷</button><button id="addPinBtn">＋ 핀</button></div><label class="field">파라미터 · 원문 JSON<textarea id="params">${esc(JSON.stringify(i.parameters||{},null,2))}</textarea></label><button id="saveParams">파라미터 적용</button><div class="sub-actions">${i.child?'<button id="childBtn">하위 셀 열기 ↗</button>':''}<button id="deleteInstance" class="danger">소자 삭제</button></div><p class="small-note">핀 이름을 기준으로 연결합니다. PDK 심벌 모양과 실제 배선 좌표는 재현하지 않습니다.</p>`;}
 else if(s?.kind==='net'){const n=c.nets.find(n=>n.name===s.id);if(!n){selected=null;return renderInspector();}html=`<span class="badge">NET / ${n.global?'GLOBAL':'LOCAL'}</span><h2>${esc(n.name)}</h2><p class="meta">${endpoints(c,n.name).length}개 연결점 · 보라색으로 전체 연결 표시</p><label class="field">넷 이름<input id="netName" value="${esc(n.name)}"></label><button id="saveNetName">넷 이름 적용</button><div class="section-label">CONNECTED ENDPOINTS</div><ul class="net-members">`+endpoints(c,n.name).map(e=>`<li><button data-member-kind="${e.kind}" data-member-id="${esc(e.id)}">${esc(e.instance)} / ${esc(e.pin)}</button></li>`).join('')+`</ul><button id="deleteNet" class="danger">넷 삭제 · 모든 핀 연결 해제</button>`;}
 else if(s?.kind==='port'){const p=c.ports.find(p=>p.name===s.id);if(!p){selected=null;return renderInspector();}html=`<span class="badge">TOP-LEVEL PORT</span><h2>${esc(p.name)}</h2><label class="field">연결 넷<select id="portNet">${netOptions(p.net)}</select></label><label class="field">방향<select id="portDirection">${['input','output','inputOutput','unknown',p.direction].filter((x,i,a)=>x&&a.indexOf(x)===i).map(v=>`<option ${v===p.direction?'selected':''}>${esc(v)}</option>`).join('')}</select></label><div class="sub-actions"><button id="newNetBtn">＋ 넷</button><button id="deletePort" class="danger">포트 삭제</button></div>`;}
 else html=`<span class="badge">${state.current.source?.type==='demo'?'EXAMPLE DESIGN':'DESIGN SNAPSHOT'}</span><h2>연결을 확인하세요</h2><p class="notes">소자나 넷을 선택하면 핀별 연결과 속성을 여기서 수정할 수 있습니다.</p><div class="info-box">⌁ <b>연결</b>을 누르고 두 핀을 클릭하세요. 다른 넷끼리 연결하면 병합할 범위를 먼저 보여줍니다.</div><p class="small-note">화면 수정은 이 프로젝트에만 반영됩니다. Cadence 원본 DB에 쓰지는 않습니다.</p><button id="newNetBtn">＋ 넷 추가</button>`;
 $('#inspector').innerHTML=html;
 if(s?.kind==='instance'){const id=s.id;$('#saveName').onclick=()=>edit('소자 이름 변경',()=>{cell().instances.find(i=>i.id===id).name=$('#instanceName').value;});$$('[data-edit-pin]').forEach(el=>el.onchange=()=>edit('핀 연결 변경',()=>assignNet(cell(),{kind:'instance',id,pin:el.dataset.editPin},el.value||null)));$$('[data-disconnect]').forEach(el=>el.onclick=()=>edit('핀 연결 해제',()=>assignNet(cell(),{kind:'instance',id,pin:el.dataset.disconnect},null)));$('#saveParams').onclick=()=>edit('파라미터 변경',()=>{const p=JSON.parse($('#params').value);cell().instances.find(i=>i.id===id).parameters=p;});$('#deleteInstance').onclick=()=>confirmAction('소자 삭제',`${cell().instances.find(i=>i.id===id).name}의 모든 핀이 제거됩니다. 다른 소자의 연결은 유지됩니다.`,()=>edit('소자 삭제',()=>{cell().instances=cell().instances.filter(i=>i.id!==id);selected=null;}),'삭제');$('#addPinBtn').onclick=()=>{modal('핀 추가','<label class="field">핀 이름<input id="pinName" placeholder="B"></label><p>새 핀은 미연결 상태로 추가됩니다.</p><div class="modal-actions"><button id="createPin" class="primary">핀 추가</button></div>');$('#createPin').onclick=()=>{const name=$('#pinName').value;if(edit('핀 추가',()=>{cell().instances.find(i=>i.id===id).pins.push({name,net:null,direction:'unknown'});}))close();};};if($('#childBtn'))$('#childBtn').onclick=()=>{cellId=cell().instances.find(i=>i.id===id).child;selected=null;render();fit();};}
 if(s?.kind==='net'){const id=s.id;$('#saveNetName').onclick=()=>edit('넷 이름 변경',()=>{const name=$('#netName').value;renameNet(cell(),id,name);const p=positions();p[key('net',name)]=p[key('net',id)];if(name!==id)delete p[key('net',id)];selected={kind:'net',id:name};});$$('[data-member-kind]').forEach(el=>el.onclick=()=>select(el.dataset.memberKind,el.dataset.memberId));$('#deleteNet').onclick=()=>confirmAction('넷 삭제',`${id}에 연결된 ${endpoints(cell(),id).length}개 연결점을 모두 미연결로 바꿉니다.`,()=>edit('넷 삭제',()=>{for(const e of endpoints(cell(),id))assignNet(cell(),e,null);cell().nets=cell().nets.filter(n=>n.name!==id);selected=null;}),'삭제');}
 if(s?.kind==='port'){const id=s.id;$('#portNet').onchange=e=>edit('포트 연결 변경',()=>assignNet(cell(),{kind:'port',id},e.target.value||null));$('#portDirection').onchange=e=>edit('포트 방향 변경',()=>{getPin(cell(),{kind:'port',id}).direction=e.target.value;});$('#deletePort').onclick=()=>confirmAction('포트 삭제',`${id} 포트를 제거합니다.`,()=>edit('포트 삭제',()=>{cell().ports=cell().ports.filter(p=>p.name!==id);selected=null;}),'삭제');}
 if($('#newNetBtn'))$('#newNetBtn').onclick=newNet;
}
function renderTable(){const c=cell();let rows=[];for(const i of c.instances)for(const p of i.pins)rows.push({owner:i.name,cell:i.cell,pin:p.name,net:p.net,direction:p.direction});for(const p of c.ports)rows.push({owner:'PORT',cell:'top-level',pin:p.name,net:p.net,direction:p.direction});$('#tableView').innerHTML=`<h2>핀 · 넷 연결표</h2><p class="notes">미연결 핀도 포함합니다. 넷 이름을 클릭하면 연결을 추적합니다.</p><div class="table-scroll"><table><thead><tr><th>INSTANCE</th><th>CELL</th><th>PIN</th><th>NET</th><th>DIRECTION</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.owner)}</td><td>${esc(r.cell)}</td><td>${esc(r.pin)}</td><td>${r.net===null?'<span class="danger">미연결</span>':`<button data-table-net="${esc(r.net)}">${esc(r.net)}</button>`}</td><td>${esc(r.direction||'unknown')}</td></tr>`).join('')}</tbody></table></div>`;$$('[data-table-net]').forEach(b=>b.onclick=()=>{selected={kind:'net',id:b.dataset.tableNet};switchView('graph');render();});}
function renderChanges(){const changes=diff(state.baseline,state.current);$('#diffCount').textContent=changes.length;$('#changesView').innerHTML='<h2>원본과 비교</h2><p class="notes">처음 가져온 구조와 현재 구조를 비교합니다. 화면상의 이동은 연결 변경에 포함하지 않습니다.</p>'+(!changes.length?'<div class="empty">원본과 연결 구조가 같습니다.</div>':changes.map(d=>`<div class="change"><code>${esc(d.path)}</code><p><span class="meta">BEFORE</span> ${esc(JSON.stringify(d.before))}</p><p><span class="meta">AFTER</span> ${esc(JSON.stringify(d.after))}</p></div>`).join(''));}
function render(){const c=cell();$('#cellSelect').innerHTML=state.current.cells.map(c=>`<option value="${esc(c.id)}" ${c.id===cellId?'selected':''}>${esc(c.name)}</option>`).join('');$('#designTitle').textContent=c.name;$('#breadcrumb').textContent=`${c.library||'LOCAL'} / ${c.view||'SCHEMATIC'}`;$('#sourceInfo').innerHTML=`<strong>${state.current.source?.type==='demo'?'예제 회로 · 실제 설계 아님':'가져온 회로'}</strong><br>${esc(c.id)}`;$('#instCount').textContent=c.instances.length;$('#netCount').textContent=c.nets.length;$('#counts').textContent=`${c.instances.length} 소자 · ${c.nets.length} 넷 · ${c.ports.length} 포트`;$('#reviewState').textContent=state.review?'사용자 검토 완료':'검토 필요';$('#reviewState').classList.toggle('done',!!state.review);$('#reviewBtn').textContent=state.review?'✓ 검토 완료 · 클릭해 해제':'✓ 현재 구조 검토 완료';$('#undoBtn').disabled=!undo.length;$('#redoBtn').disabled=!redo.length;const transformable=['instance','port','pin'].includes(selected?.kind);$('#rotateBtn').disabled=!transformable;$('#mirrorBtn').disabled=!transformable;renderExplorer();renderGraph();renderInspector();renderTable();renderChanges();const w=warnings(state.current,c);$('#warningCount').textContent=w.length?`${w.length} 항목`:'0 항목';$('#warnings').innerHTML=w.length?w.slice(0,12).map(s=>`<div class="warning">${esc(s)}</div>`).join('')+(w.length>12?`<div class="warning">외 ${w.length-12}개 · AI 문서에 전체 포함</div>`:''):'<div class="warning ok">누락된 연결 참조 없음</div>';}
function switchView(next){view=next;$('#graphView').hidden=next!=='graph';$('#tableView').hidden=next!=='table';$('#changesView').hidden=next!=='changes';$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===next));if(next==='graph')requestAnimationFrame(applyCamera);}
function newNet(){modal('넷 추가','<label class="field">넷 이름<input id="newNetName" placeholder="bias_p"></label><label><input type="checkbox" id="globalNet" style="width:auto"> Global net</label><div class="modal-actions"><button id="createNet" class="primary">넷 추가</button></div>');$('#createNet').onclick=()=>{const name=$('#newNetName').value,global=$('#globalNet').checked;if(edit('넷 추가',()=>{cell().nets.push({name,global});selected={kind:'net',id:name};}))close();};}
function setWire(value){wireMode=value;pending=null;$('#wireBtn').classList.toggle('active',value);$('#canvas').classList.toggle('wiring',value);$('#canvasHint').textContent=value?'첫 번째 핀 → 두 번째 핀 클릭 · Esc로 취소':'방향키: 화면 이동 · R: 90° 회전 · Shift+R: 좌우 반전';renderGraph();}
function pinClick(ref){if(!wireMode){selected=ref.kind==='port'?{kind:'port',id:ref.id}:{kind:'pin',id:ref.id,pin:ref.pin};render();return;}if(!pending){pending=ref;$('#canvasHint').textContent=`${ref.id} / ${ref.pin} 선택됨 · 연결할 두 번째 핀을 클릭하세요`;renderGraph();return;}const a=pending,b=ref;pending=null;const pa=getPin(cell(),a),pb=getPin(cell(),b);if(pa.net!==null&&pb.net!==null&&pa.net!==pb.net){const keep=pa.net,remove=pb.net;confirmAction('두 넷을 병합합니다',`${remove}의 ${endpoints(cell(),remove).length}개 연결점을 ${keep}로 옮깁니다. 두 핀만 연결하는 것이 아니라 두 넷 전체가 하나가 됩니다.`,()=>edit('넷 병합',()=>{mergeNets(cell(),keep,remove);selected={kind:'net',id:keep};}),'넷 병합');}else edit('핀 연결',()=>{const r=connect(cell(),a,b);if(r.net)selected={kind:'net',id:r.net};});$('#canvasHint').textContent='첫 번째 핀 → 두 번째 핀 클릭 · Esc로 취소';renderGraph();}
$('#canvas').addEventListener('pointerdown',e=>{if(e.button!==0)return;$('#canvas').focus({preventScroll:true});const pin=e.target.closest('.pin');if(pin){pinClick({kind:pin.dataset.kind,id:pin.dataset.id,pin:pin.dataset.pin});return;}const node=e.target.closest('.device,.net-node');if(node){selected={kind:node.dataset.kind,id:node.dataset.id};const pos=positions()[key(selected.kind,selected.id)];drag={type:'node',ref:clone(selected),start:{x:e.clientX,y:e.clientY},pos:{...pos},before:clone(state),moved:false};render();}else if(e.target.matches('.wire')){select('net',e.target.dataset.net);return;}else{drag={type:'pan',start:{x:e.clientX,y:e.clientY},pos:{x:camera.x,y:camera.y},moved:false};}$('#canvas').setPointerCapture(e.pointerId);});
$('#canvas').addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag.start.x,dy=e.clientY-drag.start.y;if(Math.abs(dx)+Math.abs(dy)>3)drag.moved=true;if(drag.type==='pan'){camera.x=drag.pos.x+dx;camera.y=drag.pos.y+dy;applyCamera();}else{positions()[key(drag.ref.kind,drag.ref.id)]={...drag.pos,x:Math.round((drag.pos.x+dx/camera.z)/12)*12,y:Math.round((drag.pos.y+dy/camera.z)/12)*12};renderGraph();}});
function endDrag(){if(!drag)return;if(drag.type==='node'&&drag.moved){undo.push(drag.before);if(undo.length>60)undo.shift();redo=[];persist();}if(drag.type==='pan'&&!drag.moved){selected=null;pending=null;}drag=null;render();}
$('#canvas').addEventListener('pointerup',endDrag);$('#canvas').addEventListener('pointercancel',endDrag);$('#canvas').addEventListener('wheel',e=>{e.preventDefault();const r=$('#canvas').getBoundingClientRect();zoom(e.deltaY<0?1.12:1/1.12,e.clientX-r.left,e.clientY-r.top);},{passive:false});
$('#explorer').onclick=e=>{const b=e.target.closest('button[data-kind]');if(b){select(b.dataset.kind,b.dataset.id);if(view==='graph'){const n=allNodes().find(n=>n.kind===b.dataset.kind&&n.id===b.dataset.id);if(n){const p=positions()[key(n.kind,n.id)],r=$('#canvas').getBoundingClientRect();camera.x=r.width/2-(p.x+n.w/2)*camera.z;camera.y=r.height/2-(p.y+n.h/2)*camera.z;applyCamera();}}}};
$('#search').oninput=renderExplorer;$$('[data-list]').forEach(b=>b.onclick=()=>{listMode=b.dataset.list;$$('[data-list]').forEach(x=>x.classList.toggle('active',x===b));renderExplorer();});$$('[data-view]').forEach(b=>b.onclick=()=>switchView(b.dataset.view));$('#cellSelect').onchange=e=>{cellId=e.target.value;selected=null;pending=null;render();fit();};$('#undoBtn').onclick=()=>restore('undo');$('#redoBtn').onclick=()=>restore('redo');$('#wireBtn').onclick=()=>setWire(!wireMode);$('#layoutBtn').onclick=()=>{edit('화면 자동 배치',autoLayout,{structural:false});fit();};$('#rotateBtn').onclick=()=>transformSelected('rotate');$('#mirrorBtn').onclick=()=>transformSelected('mirror');$('#fitBtn').onclick=fit;$('#zoomIn').onclick=()=>zoom(1.2);$('#zoomOut').onclick=()=>zoom(1/1.2);$('#reviewBtn').onclick=()=>{edit(state.review?'검토 표시 해제':'현재 구조를 사용자 검토 완료로 표시',()=>{state.review=state.review?null:{at:new Date().toISOString(),scope:'all cells',kind:'user-marked'};},{structural:false});};
document.addEventListener('keydown',e=>{
 if(e.isComposing||e.target.closest('input,textarea,select,[contenteditable]:not([contenteditable="false"])')||$('#modal').open)return;
 if(e.key==='Escape'){setWire(false);return;}
 const modified=e.ctrlKey||e.metaKey||e.altKey;
 if(view==='graph'&&!modified&&!drag){
   const steps={ArrowLeft:[-60,0],ArrowRight:[60,0],ArrowUp:[0,-60],ArrowDown:[0,60]};
   if(steps[e.key]){e.preventDefault();panCamera(...steps[e.key]);return;}
   if(e.code==='KeyR'||e.key.toLowerCase()==='r'){
     e.preventDefault();if(!e.repeat)transformSelected(e.shiftKey?'mirror':'rotate');return;
   }
 }
 if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();restore(e.shiftKey?'redo':'undo');}
 else if(!modified&&e.key.toLowerCase()==='w')setWire(!wireMode);
 else if(!modified&&e.key.toLowerCase()==='f')fit();
 else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();saveFile(basename()+'.project.json',JSON.stringify(bundle(state),null,2));}
});
$('#addBtn').onclick=()=>{modal('소자 / 포트 추가',`<div class="form-grid"><label class="field">유형<select id="addKind"><option value="block">사용자 셀 / 블록</option><option value="nmos">NMOS</option><option value="pmos">PMOS</option><option value="resistor">저항</option><option value="capacitor">커패시터</option><option value="port">Top-level 포트</option></select></label><label class="field">이름<input id="addName" placeholder="M6"></label><label class="field">라이브러리<input id="addLib" value="manual"></label><label class="field">참조 셀<input id="addCell" placeholder="nmos4"></label></div><label class="field">핀 이름 (쉼표로 구분)<input id="addPins" placeholder="D,G,S,B"></label><p>모든 핀은 미연결로 추가됩니다. 핀 이름은 PDK에서 확인하세요.</p><div class="modal-actions"><button class="primary" id="createInstance">추가</button></div>`);$('#addKind').onchange=()=>{const k=$('#addKind').value;$('#addPins').value=k==='nmos'||k==='pmos'?'D,G,S,B':k==='resistor'||k==='capacitor'?'PLUS,MINUS':'';$('#addCell').value=k==='nmos'||k==='pmos'?k+'4':k;};$('#createInstance').onclick=()=>{const kind=$('#addKind').value,name=$('#addName').value,lib=$('#addLib').value,ref=$('#addCell').value,pins=$('#addPins').value.split(',').map(s=>s.trim()).filter(Boolean);if(edit('새 항목 추가',()=>{if(kind==='port'){cell().ports.push({name,net:null,direction:'inputOutput'});selected={kind:'port',id:name};}else{const id=crypto.randomUUID();cell().instances.push({id,name,library:lib,cell:ref,kind,parameters:{},pins:pins.map(name=>({name,net:null,direction:'unknown'}))});selected={kind:'instance',id};}})){close();fit();}};};
function showImport(){modal('CIW 구조 가져오기',`<p>CIW 텍스트, SKILL 추출 JSON 또는 저장한 프로젝트를 선택하거나 붙여넣으세요. 파일은 브라우저에서만 읽습니다.</p><input class="file-input" id="importFile" type="file" accept=".json,.txt,application/json,text/plain" aria-label="회로 JSON 파일"><textarea id="importText" rows="11" placeholder='{"schema":"circuit-atlas/1", ...}' aria-label="구조 JSON"></textarea><label class="field">가져오기 방식<select id="importMode"><option value="replace">새 프로젝트로 열기 (현재 작업은 먼저 내보내세요)</option><option value="append">현재 프로젝트에 셀 추가</option></select></label><p class="small-note">=== 셀 / schematic === 형식의 CIW 텍스트를 지원합니다. SPICE는 지원하지 않습니다. 최대 20 MB.</p><div class="error" id="importError"></div><div class="modal-actions"><button id="saveBeforeImport">현재 프로젝트 저장</button><button class="primary" id="applyImport">가져오기</button></div>`);$('#saveBeforeImport').onclick=()=>saveFile(basename()+'.project.json',JSON.stringify(bundle(state),null,2));$('#importFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>20*1024*1024){$('#importError').textContent='20 MB를 초과합니다.';return;}$('#importText').value=await f.text();};$('#applyImport').onclick=()=>{try{const text=$('#importText').value;if(new Blob([text]).size>20*1024*1024)throw Error('20 MB를 초과합니다.');const imported=parseImport(text),mode=$('#importMode').value;if(mode==='append'){const combined=clone(state.current);combined.cells.push(...imported.current.cells);validate(combined);const ok=edit('셀 추가',()=>{state.current=combined;for(const c of imported.baseline.cells)if(!state.baseline.cells.some(x=>x.id===c.id))state.baseline.cells.push(c);Object.assign(state.layout,imported.layout);cellId=imported.current.top;selected=null;});if(!ok)return;}else{checkpoint();state=imported;cellId=state.current.top;selected=null;pending=null;render();persist();}close();fit();notify('구조를 가져왔습니다. 핀·넷 연결을 확인하세요.');}catch(e){$('#importError').textContent=e.message;}};}

$('#demoBtn').onclick=()=>confirmAction('예제 회로 열기','현재 프로젝트를 예제로 교체합니다. 필요한 작업은 먼저 프로젝트 파일로 저장하세요. 실행 취소로도 돌아갈 수 있습니다.',()=>{checkpoint();const d=demo();state={current:d,baseline:clone(d),layout:{},review:null};cellId=d.top;selected=null;render();fit();persist();},'예제 열기');
$('#exportBtn').onclick=()=>{modal('회로 구조 내보내기',`<p>다른 모델에게는 <b>AI 전달 문서</b>를 첨부하세요. 이어서 편집하려면 <b>프로젝트</b>를 저장하세요.</p><div class="export-grid"><button class="export-card" id="exportAI"><strong>↗ AI 전달 문서</strong><small>핀·넷 연결, 전체 JSON, 변경 내역,<br>불확실한 점 · Markdown</small></button><button class="export-card" id="exportProject"><strong>▣ 프로젝트</strong><small>현재 구조 + 원본 + 화면 배치<br>이어서 편집 · JSON</small></button><button class="export-card" id="exportJSON"><strong>{ } 현재 구조</strong><small>모델·후속 도구를 위한<br>명시적 핀 매핑 · JSON</small></button><button class="export-card" id="exportSVG"><strong>⌁ 연결도 이미지</strong><small>현재 셀 전체 연결도<br>확대 가능한 SVG</small></button><button class="export-card" id="exportDiff"><strong>± 변경 내역</strong><small>원본 대비 구조 차이<br>검토용 JSON (실행 패치 아님)</small></button><button class="export-card" id="copyAI"><strong>⧉ AI 문서 복사</strong><small>클립보드로 복사해<br>다른 모델에게 직접 전달</small></button></div><p class="small-note">이 앱은 외부 모델에 자동으로 전송하지 않습니다. 구조를 수정하면 검토 완료 표시가 해제됩니다.</p>`);$('#exportAI').onclick=()=>saveFile(basename()+'.ai.md',aiDocument(state),'text/markdown;charset=utf-8');$('#exportProject').onclick=()=>saveFile(basename()+'.project.json',JSON.stringify(bundle(state),null,2));$('#exportJSON').onclick=()=>saveFile(basename()+'.json',JSON.stringify(state.current,null,2));$('#exportDiff').onclick=()=>saveFile(basename()+'.changes.json',JSON.stringify({format:'circuit-atlas-diff/1',note:'Review-only semantic paths; not RFC 6902 or Cadence commands.',changes:diff(state.baseline,state.current)},null,2));$('#copyAI').onclick=async()=>{try{await navigator.clipboard.writeText(aiDocument(state));notify('AI 전달 문서를 복사했습니다.');}catch{notify('클립보드를 사용할 수 없습니다. AI 문서를 다운로드하세요.');}};$('#exportSVG').onclick=()=>{const svg=$('#canvas').cloneNode(true),bounds=graphBounds();const minX=Math.min(0,...bounds.map(b=>b.minX))-65,minY=Math.min(0,...bounds.map(b=>b.minY))-65,maxX=Math.max(500,...bounds.map(b=>b.maxX))+65,maxY=Math.max(400,...bounds.map(b=>b.maxY))+65;svg.setAttribute('viewBox',`${minX} ${minY} ${maxX-minX} ${maxY-minY}`);svg.setAttribute('width',maxX-minX);svg.setAttribute('height',maxY-minY);svg.querySelector('#viewport').removeAttribute('transform');svg.querySelectorAll('.selected,.faded,.pending').forEach(n=>n.classList.remove('selected','faded','pending'));const bg=svg.querySelector('rect');bg.setAttribute('x',minX);bg.setAttribute('y',minY);bg.setAttribute('width',maxX-minX);bg.setAttribute('height',maxY-minY);bg.setAttribute('fill','#111c23');const style=document.createElementNS('http://www.w3.org/2000/svg','style');style.textContent='.wire{fill:none;stroke:#73b5a2;stroke-width:1.6}.body{fill:#20313d;stroke:#77909d}.device-name{fill:#edf5f7;font:15px monospace}.cell-name{fill:#9aafbc;font:12px monospace}.device-type{fill:#aae2cc;font:12px monospace}.pin circle{fill:#162931;stroke:#a4e6ce;stroke-width:2}.pin text{fill:#d1e4ec;font:12px monospace}.net-node rect{fill:#1b3a33;stroke:#679681}.net-node circle{fill:#a4e6ce}.net-node text{fill:#bdeedb;font:13px monospace}.pin.unconnected circle{stroke:#f2b57c;stroke-dasharray:2 2}';svg.prepend(style);saveFile(basename()+'.svg',new XMLSerializer().serializeToString(svg),'image/svg+xml;charset=utf-8');};};
$('#helpBtn').onclick=()=>modal('Cadence 연결 안내',`<ol><li>Cadence CIW에서 아래 명령을 실행하세요.</li></ol><pre>load("/home/buet/.circuit-atlas/bridge.il")</pre><ol start="2"><li>불러올 schematic 창을 활성화하세요.</li><li>상단 <b>Cadence에서 불러오기</b> → <b>현재 회로 읽기</b> → <b>이 회로 열기</b>를 누르세요.</li></ol><p>키보드 방향키나 빈 화면 드래그로 이동합니다. R은 회전, Shift+R은 좌우 반전입니다.</p><p>심볼은 외부 단자 연결만 표시하며 내부 회로는 추정하지 않습니다.</p>`);
registerCadenceImport({button:$('#cadenceImportBtn'),modal,close,validate,
 saveProject:()=>saveFile(basename()+'.project.json',JSON.stringify(bundle(state),null,2)),
 getChangeCount:()=>diff(state.baseline,state.current).length,
 apply:doc=>{const imported=parseImport(JSON.stringify(doc));checkpoint();state=imported;cellId=state.current.top;selected=null;pending=null;setWire(false);switchView('graph');render();fit();persist();notify('Cadence 회로를 불러왔습니다.');}
});
render();requestAnimationFrame(fit);new ResizeObserver(()=>{if(view==='graph')applyCamera();}).observe($('#graphView'));
if(hasSaved){modal('저장된 작업이 있습니다','<p>이 브라우저에서 마지막으로 편집한 프로젝트를 복구할 수 있습니다. 자동 저장은 이 기기·브라우저에만 남습니다.</p><div class="modal-actions"><button id="stayDemo">예제만 보기</button><button class="primary" id="recover">저장된 작업 복구</button></div>');$('#stayDemo').onclick=close;$('#recover').onclick=()=>{try{state=parseImport(localStorage.getItem(storageKey));cellId=state.current.top;selected=null;render();fit();close();notify('저장된 프로젝트를 복구했습니다. 검토 상태는 다시 확인하세요.');}catch(e){notify('복구 실패: '+e.message);}};}
